package com.andye.warmod.radar.display.client;
import com.andye.warmod.radar.display.RadarDisplayOrientation; import net.minecraft.core.Direction; import net.minecraft.world.phys.Vec3;
public final class RadarDisplayPlaneTransform { private static final double FRONT_OFFSET=.510; private final Vec3 origin,right,normal; public RadarDisplayPlaneTransform(Direction facing){if(!facing.getAxis().isHorizontal())throw new IllegalArgumentException("Radar Display facing must be horizontal");normal=vector(facing);right=vector(RadarDisplayOrientation.screenRight(facing));origin=new Vec3(.5,0,.5).add(normal.scale(FRONT_OFFSET)).subtract(right.scale(.5));} public Vec3 point(double localX,double localY,double depth){return origin.add(right.scale(localX)).add(0,localY,0).add(normal.scale(depth));} public Vec3 normal(){return normal;} private static Vec3 vector(Direction d){return new Vec3(d.getStepX(),d.getStepY(),d.getStepZ());} }